declare(strict_types=1);
date_default_timezone_set('America/New_York');

$files = [
    'mrl_wp_images.html' => ['b64' => '', 'sha256' => '66a424fda5732fab68e35ffdf37ca8d52f4b060be74cb22d9160e043ce617aed'],
    'mrl_wp_images_data.php' => ['b64' => '', 'sha256' => '58b9f0c9d516d4f864b807ac9c4679d74bd24ddee617b0f93b713f40c42f6520'],
    'mrl_wp_images_data_v003_legacy.php' => ['b64' => '', 'sha256' => '7eee9633b82fe6af35a1271c7fdd2033000ba980d55fbc5861b9391c7100c690']
];

$report = [];
$ok = true;
$timestamp = date('Ymd_His');

foreach ($files as $name => $spec) {
    $target = __DIR__ . DIRECTORY_SEPARATOR . $name;
    $data = base64_decode($spec['b64'], true);

    if ($data === false || hash('sha256', $data) !== $spec['sha256']) {
        $report[] = 'ERROR: Invalid embedded payload for ' . $name;
        $ok = false;
        break;
    }

    if ($name === 'mrl_wp_images_data_v003_legacy.php' && is_file($target)) {
        $report[] = 'Preserved existing: ' . $name;
        continue;
    }

    if (is_file($target)) {
        $backup = $target . '.bak_' . $timestamp;
        if (!copy($target, $backup)) {
            $report[] = 'ERROR: Backup failed for ' . $name;
            $ok = false;
            break;
        }
        $report[] = 'Backup: ' . basename($backup);
    }

    $temp = $target . '.tmp_' . bin2hex(random_bytes(4));
    if (file_put_contents($temp, $data) === false ||
        hash_file('sha256', $temp) !== $spec['sha256'] ||
        !rename($temp, $target)) {
        @unlink($temp);
        $report[] = 'ERROR: Install failed for ' . $name;
        $ok = false;
        break;
    }

    $report[] = 'Installed: ' . $name;
}
